while (cx === 0 || c0 === 0 || gcd2(gcd2(cx, c0), L) !== 1);
const num = (a, b) => (a === 1 ? "" : a) + "x" + (b < 0 ? " - " + -b : " + " + b), N = norm([[cx, { x: 1 }], [c0, {}]]), e = "(" + plain(N) + ")/" + L;
