const JARDINS = []; for (let Lg = 10; Lg <= 40; Lg++) for (let l = 6; l < Lg; l++) for (let x = 1; x < l; x++) if (2 * (Lg - x) * (l - x) === Lg * l && x <= l / 2) JARDINS.push([Lg, l, x]);
