const TRI = [[3, 4, 5], [5, 12, 13], [8, 15, 17], [7, 24, 25], [20, 21, 29]];
const fr = (p, q) => "\\frac{" + p + "}{" + q + "}";
const pick3 = () => { const [a, b, c] = pk(TRI), sw = R.rand() < 0.5; return sw ? [b, a, c] : [a, b, c]; };
