const twice = (v) => { const a = Math.abs(v), t = Math.abs(a - 0.5) < 1e-6 ? "1" : Math.abs(a - Math.SQRT2 / 2) < 1e-6 ? "\\sqrt{2}" : "\\sqrt{3}"; return (v < 0 ? "-" : "") + t; };
